import { CAREERS, MONOGRAM, UPNEXT, WORDMARK } from "./logo-paths.generated";
import { cn } from "@/lib/cn";

/**
 * The approved UPNEXT Careers identity as inline SVG. Everything is drawn with `currentColor`, so the logo is black
 * on white and white on black (dark theme, footer) and never takes another colour: flat, no gradient, no effects.
 * The monogram is a faithful trace of the owner-supplied artwork; do not redraw it. Path data is generated by
 * tools/brand/build_assets.py (docs/design/BRAND_GUIDELINES.md).
 */
type Common = { className?: string; title?: string };

export function Monogram({ className, title }: Common) {
  return (
    <svg
      viewBox={`0 0 ${MONOGRAM.w} ${MONOGRAM.h}`}
      fill="currentColor"
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={cn("block", className)}
    >
      <path d={MONOGRAM.d} fillRule="evenodd" />
    </svg>
  );
}

/** UPNEXT with CAREERS beneath, CAREERS exactly as wide as UPNEXT. */
export function Wordmark({ className, title }: Common) {
  return (
    <svg
      viewBox={`-2 -2 ${WORDMARK.w + 4} ${WORDMARK.h + 4}`}
      fill="currentColor"
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={cn("block", className)}
    >
      <path transform={`translate(0 ${WORDMARK.upnextY})`} d={UPNEXT.d} />
      <path transform={`translate(0 ${CAREERS.y})`} d={CAREERS.d} />
    </svg>
  );
}

/** Horizontal lockup: monogram, then the two-line wordmark. Use at 40px high or more. */
export function Lockup({ className, title }: Common) {
  const mono = (WORDMARK.h * MONOGRAM.w) / MONOGRAM.h;
  const gap = WORDMARK.h * 0.42;
  const width = mono + gap + WORDMARK.w;
  return (
    <svg
      viewBox={`-2 -2 ${width + 4} ${WORDMARK.h + 4}`}
      fill="currentColor"
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={cn("block", className)}
    >
      <path transform={`scale(${WORDMARK.h / MONOGRAM.h})`} d={MONOGRAM.d} fillRule="evenodd" />
      <g transform={`translate(${mono + gap} 0)`}>
        <path transform={`translate(0 ${WORDMARK.upnextY})`} d={UPNEXT.d} />
        <path transform={`translate(0 ${CAREERS.y})`} d={CAREERS.d} />
      </g>
    </svg>
  );
}

/** Compact navigation logo: monogram and UPNEXT (CAREERS is too small to read at header size). */
export function NavLogo({ className, title }: Common) {
  const h = UPNEXT.capHeight * 1.18;
  const mono = (h * MONOGRAM.w) / MONOGRAM.h;
  const gap = UPNEXT.capHeight * 0.28;
  const width = mono + gap + UPNEXT.w;
  return (
    <svg
      viewBox={`-1 -1 ${width + 2} ${h + 2}`}
      fill="currentColor"
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={cn("block", className)}
    >
      <path transform={`scale(${h / MONOGRAM.h})`} d={MONOGRAM.d} fillRule="evenodd" />
      <path transform={`translate(${mono + gap} ${h / 2 + UPNEXT.capHeight / 2})`} d={UPNEXT.d} />
    </svg>
  );
}
